import { BBChart } from "@sistent/sistent";

The BBChart component supports multiple chart types for displaying data in dashboards, telemetry interfaces, and other data-driven applications.

<h2>BBChart Implementation Variants</h2>

<h3>Line Chart</h3>

Line charts are useful for displaying trends and changes across a sequence of values.

<div className="showcase">
<div className="items">
<ThemeWrapper>
<BBChart
options={{
data: {
columns: [
["CPU", 30, 45, 42, 60, 55, 70],
["Memory", 50, 52, 51, 58, 61, 65]
],
type: "line"
},
axis: {
x: {
type: "category",
categories: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
}
}
}}

/>
</ThemeWrapper>
</div>

<CodeBlock
name="line-chart"
collapsible
code={`import { BBChart } from "@sistent/sistent";

<BBChart
options={{
data: {
columns: [
["CPU", 30, 45, 42, 60, 55, 70],
["Memory", 50, 52, 51, 58, 61, 65]
],
type: "line"
},
axis: {
x: {
type: "category",
categories: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
}
}
}}
/>`}
/>

</div>

<h3>Bar Chart</h3>

Bar charts are useful for comparing values across different categories.

<div className="showcase">
<div className="items">
<ThemeWrapper>
<BBChart
options={{
data: {
columns: [
["Requests", 30, 45, 60, 40, 55]
],
type: "bar"
},
axis: {
x: {
type: "category",
categories: ["API", "Web", "DB", "Auth", "Cache"]
}
}
}}
/>
</ThemeWrapper>
</div>

<CodeBlock
name="bar-chart"
collapsible
code={`import { BBChart } from "@sistent/sistent";

<BBChart
options={{
data: {
columns: [
["Requests", 30, 45, 60, 40, 55]
],
type: "bar"
},
axis: {
x: {
type: "category",
categories: ["API", "Web", "DB", "Auth", "Cache"]
}
}
}}
/>`}
/>

</div>

<h3>Area Chart</h3>

Area charts are useful for displaying trends while emphasizing the magnitude of the values.

<div className="showcase">
<div className="items">
<ThemeWrapper>
<BBChart
options={{
data: {
columns: [
["Traffic", 20, 35, 30, 50, 45, 65]
],
type: "area"
},
axis: {
x: {
type: "category",
categories: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
}
}
}}
/>
</ThemeWrapper>
</div>

<CodeBlock
name="area-chart"
collapsible
code={`import { BBChart } from "@sistent/sistent";

<BBChart
options={{
data: {
columns: [
["Traffic", 20, 35, 30, 50, 45, 65]
],
type: "area"
},
axis: {
x: {
type: "category",
categories: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
}
}
}}
/>`}
/>

</div>

<h3>Gauge Chart</h3>

Gauge charts are useful for displaying a single value against a defined range.

<div className="showcase">
<div className="items">
<ThemeWrapper>
<BBChart
options={{
data: {
columns: [
["CPU", 72]
],
type: "gauge"
},
gauge: {
min: 0,
max: 100
}
}}
/>
</ThemeWrapper>
</div>

<CodeBlock
name="gauge-chart"
collapsible
code={`import { BBChart } from "@sistent/sistent";

<BBChart
options={{
data: {
columns: [
["CPU", 72]
],
type: "gauge"
},
gauge: {
min: 0,
max: 100
}
}}
/>`}
/>

</div>

<h3>Donut Chart</h3>

Donut charts are useful for showing the relative contribution of different categories to a whole.

<div className="showcase">
<div className="items">
<ThemeWrapper>
<BBChart
options={{
data: {
columns: [
["Compute", 45],
["Storage", 30],
["Network", 25]
],
type: "donut"
},
donut: {
title: "Resource Usage"
}
}}
/>
</ThemeWrapper>
</div>

<CodeBlock
name="donut-chart"
collapsible
code={`import { BBChart } from "@sistent/sistent";

<BBChart
options={{
data: {
columns: [
["Compute", 45],
["Storage", 30],
["Network", 25]
],
type: "donut"
},
donut: {
title: "Resource Usage"
}
}}
/>`}
/>

</div>
